{"command":"$t = Get-Content -Raw -Encoding UTF8 'tmp_stage4_draft.md'
function Cnt($s){ ($s -replace '\s','').Length }
$parts = @{}
$secs = $t -split '(?m)^(?=[②③④]|^自查)'
foreach($s in $secs){ if($s.Trim()){ $head = $s.Trim().Substring(0,[Math]::Min(6,$s.Trim().Length)); "$head => $(Cnt $s)" } }
"TOTAL(non-ws) = $(Cnt $t)"
"TOTAL(all) = $($t.Length)"","workdir":"D:\我的文档\Documents\deepseek-harness\default-workspace","description":"Count characters per section of the draft"}

{"command":"$t = Get-Content -Raw -Encoding UTF8 'tmp_stage4_v2.md'
$lines = $t -split "`r?`n"
$sec = 'none'; $h = @{}
foreach($l in $lines){
  if($l -like '①*'){ $sec='A1' } elseif($l -like '②*'){ $sec='A2' } elseif($l -like '③*'){ $sec='A3' } elseif($l -like '④*'){ $sec='A4' } elseif($l -like '自查*'){ $sec='A5' }
  if($sec -ne 'none'){ $c = ($l -replace '\s','').Length; if($h.ContainsKey($sec)){ $h[$sec] = $h[$sec] + $c } else { $h[$sec] = $c } }
}
foreach($k in 'A1','A2','A3','A4','A5'){ "$k = $($h[$k])" }
$s3 = ($lines | Where-Object { $_ -like '明天净可用210分钟，六项需求380分钟，装不下*' }) -join ''
"S3body = $(($s3 -replace '\s','').Length)"
"T3body = $((($s3 -replace '[^一-龥]', '').Length)) 汉字"
"TOTAL = $((($t -replace '\s','').Length))"","description":"Count chars per section in v2 draft"}

{"command":"$t = Get-Content -Raw -Encoding UTF8 'tmp_stage4_v3.md'
