  if($l.StartsWith([string][char]0x2460)){$sec='S1'}elseif($l.StartsWith([string][char]0x2461)){$sec='S2'}elseif($l.StartsWith([string][char]0x2462)){$sec='S3'}elseif($l.StartsWith([string][char]0x2463)){$sec='S4'}elseif($l.StartsWith('自查')){$sec='S5'}
  $c=(($l -replace '\s','')).Length
  if($h.ContainsKey($sec)){$h[$sec]=$h[$sec]+$c}else{$h[$sec]=$c}
}
foreach($k in 'S1','S2','S3','S4','S5'){"$k = $($h[$k])"}
"TOTAL = $((($t -replace '\s','').Length))"
$b3 = $lines | Where-Object { $_ -like '明天净可用210分钟，六项需求380分钟。保*' }
"S3body = $((($b3 -replace '\s','').Length))"
$b2 = $lines | Where-Object { $_ -like '明天净可用210分钟、六项需求380分钟*' }
"S2body = $((($b2 -replace '\s','').Length))"","description":"Count v3 sections and body lengths"}

